package org.apache.commons.text.similarity;

import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.CharBuffer;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class LevenshteinDistance_ESTest_test16 extends LevenshteinDistance_ESTest_scaffolding {

    /**
     * Two identical character sequences have a Levenshtein distance of 0,
     * both with the default (unlimited) instance and with a threshold-limited
     * instance whose threshold is 0.
     */
    @Test(timeout = 4000)
    public void distanceBetweenIdenticalSequencesIsZero() throws Throwable {
        // A buffer of two identical (default '�') characters, compared against itself.
        CharBuffer identicalSequence = CharBuffer.wrap(new char[2]);

        // Default instance: no threshold, so the exact distance is computed.
        LevenshteinDistance unlimitedDistance = LevenshteinDistance.getDefaultInstance();
        Integer unlimitedResult = unlimitedDistance.apply((CharSequence) identicalSequence, (CharSequence) identicalSequence);
        assertEquals(0, (int) unlimitedResult);

        // Threshold-limited instance with threshold 0: a distance of 0 is within the limit.
        LevenshteinDistance limitedDistance = new LevenshteinDistance(unlimitedResult);
        Integer limitedResult = limitedDistance.apply((CharSequence) identicalSequence, (CharSequence) identicalSequence);
        assertEquals(0, (int) limitedResult);
    }
}
